// La forma de los datos está en el encabezado de revisar.js. Todas las lecturas fueron escritas para este sitio.

/** Reloj de agujas para las preguntas de la hora (h de 0 a 23, m de 0 a 59). */
function reloj(h, m) {
  const punto = (grados, radio) => {
    const a = ((grados - 90) * Math.PI) / 180;
    return [(50 + radio * Math.cos(a)).toFixed(1), (50 + radio * Math.sin(a)).toFixed(1)];
  };
  const numeros = Array.from({ length: 12 }, (_, i) => {
    const [x, y] = punto((i + 1) * 30, 36);
    return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="central" font-size="9" font-family="sans-serif" fill="currentColor">${i + 1}</text>`;
  }).join("");
  const [mx, my] = punto(m * 6, 32);
  const [hx, hy] = punto((h % 12) * 30 + m / 2, 20);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="150" height="150">`
    + `<circle cx="50" cy="50" r="46" fill="none" stroke="currentColor" stroke-width="3"/>${numeros}`
    + `<line x1="50" y1="50" x2="${hx}" y2="${hy}" stroke="currentColor" stroke-width="4.5" stroke-linecap="round"/>`
    + `<line x1="50" y1="50" x2="${mx}" y2="${my}" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>`
    + `<circle cx="50" cy="50" r="2.5" fill="currentColor"/></svg>`;
}

/** Un cuadro con letra para las figuras de pasos. */
const cuadro = (x, letra, dibujo) => `<g transform="translate(${x} 0)">`
  + `<rect x="4" y="4" width="92" height="132" rx="8" stroke-opacity="0.35"/>`
  + `<text x="50" y="24" text-anchor="middle" font-size="16" font-weight="bold" fill="currentColor" stroke="none">${letra}</text>${dibujo}</g>`;

const HOJA_DOBLADA = `<rect x="18" y="66" width="64" height="46"/>`;
const RAYAS = (extra = "") => [28, 38, 48, 58, 68].map(x => `<line x1="${x}" y1="112" x2="${x}" y2="74"${extra}/>`).join("");
const TUBO = `<ellipse cx="50" cy="52" rx="24" ry="7"/><line x1="26" y1="52" x2="26" y2="114"/><line x1="74" y1="52" x2="74" y2="114"/>`
  + `<path d="M26 114 A24 7 0 0 0 74 114"/>` + [36, 44, 52, 60, 68].map(x => `<line x1="${x}" y1="66" x2="${x}" y2="104"/>`).join("");

/** Dibujos (desordenados) de los pasos para hacer un farol de papel. */
const FAROL = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 140" width="500" height="140" fill="none" stroke="currentColor" stroke-width="2">`
  // A: cortar por las rayas (tijera)
  + cuadro(0, "A", HOJA_DOBLADA + RAYAS()
    + `<circle cx="24" cy="40" r="6"/><circle cx="24" cy="56" r="6"/><line x1="29" y1="43" x2="62" y2="60"/><line x1="29" y1="53" x2="62" y2="38"/>`)
  // B: doblar la hoja a la mitad
  + cuadro(100, "B", `<rect x="18" y="38" width="64" height="80"/><line x1="18" y1="78" x2="82" y2="78" stroke-dasharray="5 4"/>`
    + `<path d="M74 42 C 92 50, 92 68, 76 76"/><path d="M76 76 l 8 -1 M76 76 l 1 -8"/>`)
  // C: pegar la tira de arriba (agarradera)
  + cuadro(200, "C", TUBO + `<path d="M30 50 C 30 22, 70 22, 70 50" stroke-width="3"/>`)
  // D: trazar rayas con regla y lápiz
  + cuadro(300, "D", HOJA_DOBLADA + RAYAS(` stroke-dasharray="3 3" stroke-width="1.5"`)
    + `<line x1="86" y1="34" x2="70" y2="60" stroke-width="7"/><path d="M73 61.8 L67 58.2 L65.8 66.8 Z" fill="currentColor"/>`)
  // E: enrollar y pegar como tubo
  + cuadro(400, "E", TUBO)
  + `</svg>`;

